import { buildMetricMap } from './metrics';
import { metricObservations } from './observations';
import { initialModels } from './models';
import { calculateIndexScores } from '../engine/calculator';

// Each dimension has its own completeness; capability eligibility is independent.
export function buildComparisonScores() {
  const map = new Map<string, number>();
  for (const id of ['composite-speed-score', 'composite-affordability-score']) {
    for (const result of calculateIndexScores(id, initialModels, buildMetricMap(), metricObservations)) {
      if (result.isEligible) map.set(`${result.model.id}:${id}`, result.score);
    }
  }
  return map;
}

