import type { IndexCatalog, RawMetricDefinition } from '../types';
import savedCatalog from './indexCatalog.json';
import { rawMetrics as rawDefinitions } from './rawMetrics';
import { createCatalogMetricMap } from '../engine/catalog';

const catalog = savedCatalog as IndexCatalog;
export const compositeMetrics = catalog.compositeMetrics;
export const publicCompositeMetrics = compositeMetrics.filter(metric => !metric.fallbackOnly);
export const rawMetrics = [...createCatalogMetricMap(rawDefinitions, catalog).values()]
  .filter((metric): metric is RawMetricDefinition => metric.kind === 'raw');

export function buildMetricMap(currentCatalog: IndexCatalog = catalog) {
  return createCatalogMetricMap(rawDefinitions, currentCatalog);
}

