import { initialModels } from './models';
import { buildMetricMap, compositeMetrics, rawMetrics } from './metrics';
import { metricObservations } from './observations';
import { publishedIndices } from './publishedIndices';
import { validateMetricDAG } from '../engine/dag';
import { requiresVision } from '../engine/fallbackSources';

export interface ValidationReport {
  isValid: boolean;
  errors: string[];
  warnings: string[];
  stats: {
    modelCount: number;
    rawMetricCount: number;
    compositeMetricCount: number;
    observationCount: number;
    indexCount: number;
  };
}

// Known fabricated, unestablished, or legacy test domains that must never be permitted in verified data
const DISALLOWED_DOMAINS = [
  'terminalbench.org',
  'swe-atlas.ai',
  'babyvision-bench.ai'
];

export function validateDataset(): ValidationReport {
  const errors: string[] = [];
  const warnings: string[] = [];

  const modelIds = new Set(initialModels.map((m) => m.id));
  const rawMetricIds = new Set(rawMetrics.map((r) => r.id));
  const metricMap = buildMetricMap();

  const ISO_DATE_REGEX = /^\d{4}-\d{2}-\d{2}$/;
  const DEEP_URL_REGEX = /^https?:\/\/[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}(\/.*)?$/;

  // 1. Validate models
  const seenModelIds = new Set<string>();
  for (const model of initialModels) {
    if (seenModelIds.has(model.id)) {
      errors.push(`Duplicate model ID detected: '${model.id}'.`);
    }
    seenModelIds.add(model.id);
    if (!['supported', 'unsupported', 'unknown'].includes(model.visionInput)) {
      errors.push(`Model '${model.id}' needs an explicit vision support state.`);
    }
    if (model.visionInput !== 'unknown' && (!model.visionSourceUrl || !DEEP_URL_REGEX.test(model.visionSourceUrl))) {
      errors.push(`Model '${model.id}' needs a source for its vision capability.`);
    }

    if (!model.name || !model.organization) {
      errors.push(`Model '${model.id}' missing required name or organization.`);
    }

    if (!['api', 'open_weights', 'hosted'].includes(model.access)) {
      errors.push(`Model '${model.id}' has invalid access type '${model.access}'.`);
    }

    if (!ISO_DATE_REGEX.test(model.releaseDate)) {
      errors.push(`Model '${model.id}' releaseDate '${model.releaseDate}' is not ISO YYYY-MM-DD.`);
    }

    if (model.contextWindow <= 0 || !isFinite(model.contextWindow)) {
      errors.push(`Model '${model.id}' contextWindow must be a positive finite integer.`);
    }
  }

  // 2. Validate raw metrics and anchor semantics
  const seenMetricIds = new Set<string>();
  for (const raw of rawMetrics) {
    if (seenMetricIds.has(raw.id)) {
      errors.push(`Duplicate raw metric ID detected: '${raw.id}'.`);
    }
    seenMetricIds.add(raw.id);
    for (const fallbackId of raw.fallbackMetricIds ?? []) {
      const fallback = metricMap.get(fallbackId);
      if (!fallback || fallbackId === raw.id) {
        errors.push(`Raw metric '${raw.id}' has an invalid fallback '${fallbackId}'.`);
      }
      if (raw.requiresVisionInput && fallback && !requiresVision(fallback, metricMap)) {
        errors.push(`Vision metric '${raw.id}' cannot use text-only fallback '${fallbackId}'.`);
      }
    }

    const { lowerAnchor, upperAnchor } = raw.normalization;
    if (!isFinite(lowerAnchor) || !isFinite(upperAnchor)) {
      errors.push(`Raw metric '${raw.id}' anchors must be finite numbers.`);
    }

    if (lowerAnchor >= upperAnchor) {
      errors.push(
        `Raw metric '${raw.id}' lowerAnchor (${String(lowerAnchor)}) must be strictly less than upperAnchor (${String(upperAnchor)}).`
      );
    }

    if (!raw.unit || !raw.name) {
      errors.push(`Raw metric '${raw.id}' missing name or unit.`);
    }

    if (!raw.source.primarySourceUrl || !DEEP_URL_REGEX.test(raw.source.primarySourceUrl)) {
      errors.push(`Raw metric '${raw.id}' has invalid primarySourceUrl: '${raw.source.primarySourceUrl}'.`);
    }

    // Check disallowed domains
    for (const badDomain of DISALLOWED_DOMAINS) {
      if (raw.source.primarySourceUrl.includes(badDomain)) {
        errors.push(`Raw metric '${raw.id}' uses disallowed or unverified domain: '${badDomain}'.`);
      }
    }
  }

  // 3. Validate composite metrics DAG
  for (const comp of compositeMetrics) {
    try {
      validateMetricDAG(comp.id, metricMap);
    } catch (error: unknown) {
      errors.push(`Composite metric '${comp.id}' validation failed: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  // 4. Validate published indices
  for (const idx of publishedIndices) {
    if (!metricMap.has(idx.rootMetricId)) {
      errors.push(`Published index '${idx.id}' references non-existent rootMetricId '${idx.rootMetricId}'.`);
    } else {
      try {
        validateMetricDAG(idx.rootMetricId, metricMap);
      } catch (error: unknown) {
        errors.push(`Index '${idx.id}' DAG error: ${error instanceof Error ? error.message : String(error)}`);
      }
    }
  }

  // 5. Multiple effort observations are allowed; scoring selects the best compatible result.
  for (const obs of metricObservations) {
    const key = `${obs.modelId}:${obs.metricId}`;

    if (!modelIds.has(obs.modelId)) {
      errors.push(`Observation references unknown modelId '${obs.modelId}'.`);
    }
    if (!rawMetricIds.has(obs.metricId)) {
      errors.push(`Observation references non-raw metricId '${obs.metricId}'.`);
    }

    if (!isFinite(obs.value)) {
      errors.push(`Observation '${key}' value '${String(obs.value)}' is not a finite number.`);
    }

    if (!ISO_DATE_REGEX.test(obs.observationDate)) {
      errors.push(`Observation '${key}' observationDate '${obs.observationDate}' must match YYYY-MM-DD.`);
    }

    if (!obs.sourceUrl || !DEEP_URL_REGEX.test(obs.sourceUrl)) {
      errors.push(`Observation '${key}' requires a valid deep source URL (found: '${obs.sourceUrl}').`);
    }

    // Reject disallowed/unverified domains
    for (const badDomain of DISALLOWED_DOMAINS) {
      if (obs.sourceUrl.includes(badDomain)) {
        errors.push(`Observation '${key}' sourceUrl contains disallowed or unverified domain: '${badDomain}'.`);
      }
    }

    // Mandatory Provenance Rule: Quality, vision, and knowledge benchmarks MUST include exact scaffold and reasoning budget
    const def = metricMap.get(obs.metricId);
    if (def?.kind === 'raw' && def.requiresVisionInput && initialModels.find(model => model.id === obs.modelId)?.visionInput === 'unsupported') {
      errors.push(`Observation '${key}' conflicts with confirmed unsupported vision.`);
    }
    if (def?.kind === 'raw' && (def.family === 'quality' || def.family === 'vision' || def.family === 'knowledge')) {
      if (!obs.scaffoldOrHarness || obs.scaffoldOrHarness.trim() === '') {
        errors.push(`Observation '${key}' missing mandatory scaffoldOrHarness provenance metadata.`);
      }
      if (!obs.reasoningBudget || obs.reasoningBudget.trim() === '') {
        errors.push(`Observation '${key}' missing mandatory reasoningBudget provenance metadata.`);
      }
    }
  }

  return {
    isValid: errors.length === 0,
    errors,
    warnings,
    stats: {
      modelCount: initialModels.length,
      rawMetricCount: rawMetrics.length,
      compositeMetricCount: compositeMetrics.length,
      observationCount: metricObservations.length,
      indexCount: publishedIndices.length
    }
  };
}

src/engine/benchmarkResolver.ts:
import type { CrossEffortCalibration, FallbackCalibration, LeafContribution, MetricDefinition, MetricObservation, ModelRelease, RawMetricDefinition } from '../types';
import { metricSignature, predictCalibration } from './calibration';
import { normalizeRawValue } from './normalizer';
import { readFallbackSource, requiresVision } from './fallbackSources';

export function resolveBenchmark(
  model: ModelRelease, target: RawMetricDefinition, effectiveWeight: number,
  metrics: Map<string, MetricDefinition>, observations: Map<string, MetricObservation>,
  calibrations: FallbackCalibration[], crossEffort?: CrossEffortCalibration
): LeafContribution {
  const primary = observations.get(`${model.id}:${target.id}`);
  const result: LeafContribution = {
    rawMetric: target, rawValue: primary?.value ?? null, state: 'missing', hasEvidence: false,
    normalizedValue: 0, effectiveWeight, pointsContributed: 0, explanation: 'No usable result.'
  };
  if (target.requiresVisionInput && model.visionInput === 'unsupported') {
    if (primary) return { ...result, explanation: 'Vision metadata conflicts with a recorded image evaluation; review required.' };
    return { ...result, state: 'unsupported', hasEvidence: true, explanation: 'Cannot accept required image input; assigned zero points.' };
  }
  if (primary) {
    const normalizedValue = normalizeRawValue(primary.value, target);
    return { ...result, state: 'measured', hasEvidence: true, sourceObservation: primary, sourceMetric: target,
      normalizedValue, pointsContributed: normalizedValue * effectiveWeight, explanation: 'Preferred benchmark measurement.' };
  }
  const pendingSources: string[] = [];
  for (const sourceId of target.fallbackMetricIds ?? []) {
    const source = metrics.get(sourceId);
    if (!source || (target.requiresVisionInput && !requiresVision(source, metrics))) continue;
    const evidence = readFallbackSource(model, source, metrics, observations,
      ['quality', 'knowledge', 'vision'].includes(target.family) ? crossEffort : undefined);
    if (!evidence) continue;
    const calibration = calibrations.find(route => route.targetMetricId === target.id && route.sourceMetricId === sourceId
      && route.targetSignature === metricSignature(target) && route.sourceSignature === metricSignature(source, metrics));
    if (calibration?.status !== 'ready' || !calibration.scale) {
      pendingSources.push(source.name);
      continue;
    }
    const scaled = calibration.scale;
    const normalizedValue = predictCalibration(scaled, evidence.score);
    const usesCrossEffort = evidence.components.some(part => part.state === 'cross-effort');
    return { ...result, state: 'estimated', hasEvidence: true, sourceMetric: source,
      sourceObservation: source.kind === 'raw' ? evidence.components[0]?.observation : undefined,
      sourceComponents: source.kind === 'composite' || evidence.components.some(part => part.state !== 'measured')
        ? evidence.components : undefined,
      normalizedValue, pointsContributed: normalizedValue * effectiveWeight,
      perfectVisionValue: predictCalibration(scaled, evidence.perfectVisionScore),
      calibrationId: calibration.id, estimateKind: usesCrossEffort ? 'cross-effort' : 'scaled',
      crossEffort: usesCrossEffort ? crossEffort : undefined,
      explanation: `Scale-adjusted from ${source.name} using ${calibration.method === 'manual' ? 'manual calibration' : `paired averages (${String(calibration.pairedCount)} models)`}.`
        + (usesCrossEffort && crossEffort ? ` Cross-effort estimate: missing source inputs use this release's real Top measurements × ${crossEffort.factor.toFixed(4)} before benchmark conversion.` : '')
        + (pendingSources.length ? ` Skipped ${pendingSources.join(', ')}: calibration required.` : '') };
  }
  return pendingSources.length ? { ...result, explanation: `Result recorded for ${pendingSources.join(', ')}; calibration required before it can contribute points or coverage.` } : result;
}

