import {
  CalculatedModelScore,
  FallbackCalibration,
  LeafContribution,
  MetricDefinition,
  MetricObservation,
  ModelRelease,
  RawMetricDefinition
} from '../types';
import { resolveEffectiveLeafWeights } from './dag';
import { fallbackCalibrations } from '../data/calibrations';
import { resolveBenchmark } from './benchmarkResolver';
import { calculateScoreUncertainty } from './uncertainty';
import { selectBestObservations } from './observations';
import { buildCrossEffortCalibrations, estimateCrossEffort } from './crossEffort';

/**
 * Calculates synthetic index scores for all models against a root metric definition.
 * Measurements, calibrated estimates and confirmed unsupported vision resolve a component.
 * At least 95% evidence coverage qualifies for ranking; missing weight adds to uncertainty.
 * Weights are never redistributed.
 */
export function calculateIndexScores(
  rootMetricId: string,
  models: ModelRelease[],
  metricMap: Map<string, MetricDefinition>,
  observations: MetricObservation[],
  calibrations: FallbackCalibration[] = fallbackCalibrations,
  evidenceModels: ModelRelease[] = models
): CalculatedModelScore[] {
  // 1. Flatten root metric into effective leaf weights
  const effectiveLeaves = resolveEffectiveLeafWeights(rootMetricId, metricMap);

  const obsMap = selectBestObservations(evidenceModels, metricMap, observations);
  const crossEffort = buildCrossEffortCalibrations(evidenceModels, metricMap, obsMap);

  // 3. Score each model
  const modelScores: CalculatedModelScore[] = models.map((model) => {
    let totalScore = 0;
    let coveredWeight = 0;
    let estimatedWeight = 0;
    let crossEffortWeight = 0;
    let unsupportedWeight = 0;
    let perfectVisionGain = 0;
    let hasAllRequiredObservations = true;
    const leafBreakdown: LeafContribution[] = [];

    for (const leaf of effectiveLeaves) {
      const rawDef = metricMap.get(leaf.rawMetricId) as RawMetricDefinition;
      const estimated = estimateCrossEffort(
        resolveBenchmark(model, rawDef, leaf.effectiveWeight, metricMap, obsMap, calibrations),
        model, crossEffort.get(model.id), obsMap);
      const resolved = estimated.state === 'missing' && crossEffort.has(model.id)
        ? resolveBenchmark(model, rawDef, leaf.effectiveWeight, metricMap, obsMap, calibrations, crossEffort.get(model.id))
        : estimated;
      totalScore += resolved.pointsContributed;
      const perfectVisionValue = resolved.state === 'unsupported' ? 100 : resolved.perfectVisionValue ?? resolved.normalizedValue;
      perfectVisionGain += (perfectVisionValue - resolved.normalizedValue) * leaf.effectiveWeight;
      if (resolved.state === 'measured') coveredWeight += leaf.effectiveWeight;
      if (resolved.state === 'estimated') estimatedWeight += leaf.effectiveWeight;
      if (resolved.estimateKind === 'cross-effort') crossEffortWeight += leaf.effectiveWeight;
      if (resolved.state === 'unsupported') unsupportedWeight += leaf.effectiveWeight;
      if (resolved.state === 'missing' && leaf.effectiveWeight > 0) hasAllRequiredObservations = false;
      leafBreakdown.push(resolved);
    }

    // Sort leaf breakdown by effective weight descending
    leafBreakdown.sort((a, b) => b.effectiveWeight - a.effectiveWeight);

    const evidencePercent = leafBreakdown.reduce((sum, leaf) =>
      sum + (leaf.hasEvidence ? leaf.effectiveWeight : 0), 0) * 100;
    // Account only for floating-point arithmetic at the inclusive 95% boundary, not display rounding.
    const isEligible = evidencePercent >= 95 - 1e-10;
    // Display rounding must not suggest an incomplete model is complete or an ineligible model meets 95%.
    const coveragePercent = hasAllRequiredObservations ? 100
      : Math.min(isEligible ? 99.9 : 94.9, Math.round(evidencePercent * 10) / 10);

    return {
      model,
      score: totalScore,
      rank: null, // Assigned strictly to eligible models below
      isEligible,
      coveragePercent,
      measuredPercent: coveredWeight * 100,
      estimatedPercent: estimatedWeight * 100,
      crossEffortEstimatedPercent: crossEffortWeight * 100,
      unsupportedPercent: unsupportedWeight * 100,
      perfectVisionScore: Math.min(100, totalScore + perfectVisionGain),
      uncertainty: calculateScoreUncertainty(leafBreakdown, isEligible),
      leafBreakdown
    };
  });

  // 4. Split into Eligible (Official) and Ineligible (Provisional) cohorts
  const eligibleModels = modelScores.filter((m) => m.isEligible);
  const provisionalModels = modelScores.filter((m) => !m.isEligible);

  const scoreComparator = (a: CalculatedModelScore, b: CalculatedModelScore) => {
    if (b.score !== a.score) {
      return b.score - a.score;
    }
    const topLeafA = a.leafBreakdown[0]?.pointsContributed ?? 0;
    const topLeafB = b.leafBreakdown[0]?.pointsContributed ?? 0;
    if (topLeafB !== topLeafA) {
      return topLeafB - topLeafA;
    }
    return a.model.name.localeCompare(b.model.name);
  };

  eligibleModels.sort(scoreComparator);
  provisionalModels.sort(scoreComparator);

  // 5. Assign official ranks ONLY to eligible models
  let currentRank = 1;
  for (let i = 0; i < eligibleModels.length; i++) {
    if (i > 0 && eligibleModels[i].score < eligibleModels[i - 1].score) {
      currentRank = i + 1;
    }
    eligibleModels[i].rank = currentRank;
  }

  // Provisional models keep rank = null
  for (const prov of provisionalModels) {
    prov.rank = null;
  }

  // Return official eligible models first, followed by provisional models
  return [...eligibleModels, ...provisionalModels];
}

