import type { FallbackCalibration, ManualFallbackCalibration, MetricDefinition, RawMetricDefinition } from '../types';

import { resolveEffectiveLeafWeights } from './dag';
import { requiresVision } from './fallbackSources';

export const CALIBRATION_ALGORITHM = 'paired-mean-manual-v3';

export function metricSignature(metric: MetricDefinition, metrics = new Map<string, MetricDefinition>()): string {
  if (metric.kind === 'composite') return JSON.stringify([metric.id, metric.version,
    resolveEffectiveLeafWeights(metric.id, metrics).filter(leaf => leaf.effectiveWeight > 0).map(leaf =>
      [leaf.effectiveWeight, metricSignature(metrics.get(leaf.rawMetricId) as RawMetricDefinition)])]);
  return JSON.stringify([metric.id, metric.version, metric.direction, metric.requiresVisionInput,
    metric.normalization.scale ?? 'linear', metric.normalization.lowerAnchor, metric.normalization.upperAnchor]);
}

export function predictCalibration(scale: NonNullable<FallbackCalibration['scale']>, x: number): number {
  return Math.max(0, Math.min(100, x * scale.targetAnchor / scale.sourceAnchor));
}

/** Offline scale alignment only; benchmark agreement does not determine score or eligibility. */
export function buildCalibration(
  id: string, target: RawMetricDefinition, source: MetricDefinition,
  preferredReferenceScores: { modelId: string; score: number }[],
  fallbackReferenceScores: { modelId: string; score: number }[],
  metrics = new Map<string, MetricDefinition>([[target.id, target], [source.id, source]]),
  manual?: ManualFallbackCalibration
): FallbackCalibration {
  const sources = new Map(fallbackReferenceScores.map(result => [result.modelId, result.score]));
  const pairs = preferredReferenceScores.flatMap(result => {
    const sourceScore = sources.get(result.modelId);
    return sourceScore === undefined ? [] : [{ primary: result.score, secondary: sourceScore }];
  });
  const result: FallbackCalibration = {
    id, targetMetricId: target.id, sourceMetricId: source.id,
    targetSignature: metricSignature(target), sourceSignature: metricSignature(source, metrics),
    targetReferenceCount: preferredReferenceScores.length, sourceReferenceCount: fallbackReferenceScores.length,
    pairedCount: pairs.length, method: null,
    status: 'manual-required', reason: '', scale: null
  };
  if (target.requiresVisionInput && !requiresVision(source, metrics)) {
    return { ...result, reason: 'A text-only evaluation cannot establish native vision performance.' };
  }
  const sourceAnchor = pairs.length ? pairs.reduce((sum, pair) => sum + pair.secondary, 0) / pairs.length : 0;
  if (pairs.length && sourceAnchor > 0) {
    return { ...result, status: 'ready', method: 'paired-mean',
      reason: `Ratio of mean primary to mean secondary points across ${String(pairs.length)} overlapping models.`,
      scale: { sourceAnchor, targetAnchor: pairs.reduce((sum, pair) => sum + pair.primary, 0) / pairs.length } };
  }
  if (manual?.targetMetricId === target.id && manual.sourceMetricId === source.id
      && manual.targetSignature === result.targetSignature && manual.sourceSignature === result.sourceSignature
      && Number.isFinite(manual.factor) && manual.factor >= 0) {
    return { ...result, status: 'ready', method: 'manual', reason: manual.rationale,
      scale: { sourceAnchor: 1, targetAnchor: manual.factor } };
  }
  return { ...result, reason: manual
    ? 'Manual calibration does not match the current benchmark definitions; review and recalibrate.'
    : pairs.length ? 'The paired secondary mean is zero; manual calibration required.'
      : 'No overlapping direct model measurements; manual calibration required.' };
}

