import type { CalibrationReferenceData, FallbackCalibration, ManualFallbackCalibration, MetricDefinition, MetricObservation, ModelRelease } from '../types';
import { buildCalibration, CALIBRATION_ALGORITHM } from './calibration';
import { readFallbackSource } from './fallbackSources';
import { OBSERVATION_SELECTION_POLICY, selectBestObservations } from './observations';
import { assignReasoningObservations, observationEffort } from './reasoningConfigurations';

/** Used by offline snapshots and Studio previews; production reads the saved snapshot. */
export function generateFallbackCalibrations(
  models: ModelRelease[], metrics: Map<string, MetricDefinition>, observations: MetricObservation[],
  manualCalibrations: ManualFallbackCalibration[] = [],
  references: CalibrationReferenceData = { models: [], observations: [] }
) {
  // A release may appear in both pools. Merge by stable ID before pairing so it counts once.
  const effortOrder = ['max', 'xhigh', 'high', 'medium', 'low'];
  const externalModels = references.models.filter(reference => !models.some(model => model.id === reference.id)).flatMap(reference => {
    const records = references.observations.filter(observation => observation.modelId === reference.id);
    const efforts = [...new Set(records.map(observationEffort).filter((effort): effort is string => effort !== null))]
      .sort((a, b) => (effortOrder.includes(a) ? effortOrder.indexOf(a) : 99) - (effortOrder.includes(b) ? effortOrder.indexOf(b) : 99));
    return (efforts.length ? efforts : [null]).map((effort, index) => ({
      ...reference,
      id: index === 0 ? reference.id : `${reference.id}--reference-${encodeURIComponent(String(effort))}`,
      reasoningConfiguration: { releaseId: reference.id, effort, tier: index === 0 ? 'top' as const : 'lowest' as const,
        basis: 'documented-settings' as const, sourceUrl: records[0]?.sourceUrl ?? '' }
    }));
  });
  const referenceModels = [...externalModels, ...models];
  const selected = selectBestObservations(referenceModels, metrics,
    [...assignReasoningObservations(referenceModels, references.observations), ...observations]);
  const referenceResults = (metric: MetricDefinition) => referenceModels.flatMap(model => {
    const result = readFallbackSource(model, metric, metrics, selected);
    // Policy zeros resolve coverage but are not benchmark measurements for reference scales.
    return result?.components.every(part => part.state === 'measured') ? [{ modelId: model.id, ...result }] : [];
  });
  const calibrations: FallbackCalibration[] = [];
  const evidence = [];
  for (const target of metrics.values()) {
    if (target.kind !== 'raw') continue;
    for (const sourceId of target.fallbackMetricIds ?? []) {
      const source = metrics.get(sourceId);
      if (!source) throw new Error(`Unknown fallback ${sourceId}`);
      const allPreferred = referenceResults(target);
      const allFallback = referenceResults(source);
      // Keep one matched setting per release so releases with more published efforts do not dominate.
      const pairedByRelease = new Map<string, (typeof allPreferred)[number]>();
      for (const result of allPreferred) {
        if (!allFallback.some(entry => entry.modelId === result.modelId)) continue;
        const model = referenceModels.find(entry => entry.id === result.modelId);
        const releaseId = model?.reasoningConfiguration?.releaseId ?? result.modelId;
        const previous = pairedByRelease.get(releaseId);
        if (!previous || result.score > previous.score) pairedByRelease.set(releaseId, result);
      }
      const pairedIds = new Set([...pairedByRelease.values()].map(result => result.modelId));
      const preferredResults = allPreferred.filter(result => pairedIds.has(result.modelId) || !allFallback.some(entry => entry.modelId === result.modelId));
      const fallbackResults = allFallback.filter(result => pairedIds.has(result.modelId) || !allPreferred.some(entry => entry.modelId === result.modelId));
      calibrations.push(buildCalibration(`${CALIBRATION_ALGORITHM}:${target.id}:${source.id}`, target, source,
        preferredResults, fallbackResults, metrics,
        manualCalibrations.find(entry => entry.targetMetricId === target.id && entry.sourceMetricId === source.id)));
      const pairedModelIds = preferredResults.filter(result => fallbackResults.some(source => source.modelId === result.modelId))
        .map(result => result.modelId);
      evidence.push({ target, source, preferredResults, fallbackResults, pairedModelIds });
    }
  }
  return { calibrations, report: { algorithm: CALIBRATION_ALGORITHM, observationSelection: OBSERVATION_SELECTION_POLICY,
    models: referenceModels.map(model => ({ id: model.id, name: model.name, leaderboard: models.some(entry => entry.id === model.id) })), evidence } };
}

