import type { CompositeMetricDefinition, IndexCatalog, MetricDefinition, MetricFamily, PublishedIndex, RawMetricDefinition } from '../types';
import { resolveEffectiveLeafWeights, validateMetricDAG } from './dag';
import { requiresVision } from './fallbackSources';

export const sharedComparisonIds = ['composite-speed-score', 'composite-affordability-score'];

function record(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('Expected a catalog object.');
  return value as Record<string, unknown>;
}

function text(value: unknown, label: string, allowEmpty = false): string {
  if (typeof value !== 'string' || (!allowEmpty && !value.trim())) throw new Error(`${label} is required.`);
  return value;
}

function id(value: unknown): string {
  const result = text(value, 'ID');
  if (!/^[a-z0-9][a-z0-9_-]*$/.test(result)) throw new Error('IDs must use lowercase letters, numbers, hyphens or underscores.');
  return result;
}

function isoDate(value: unknown, label: string): string {
  const result = text(value, label);
  const parsed = new Date(`${result}T00:00:00Z`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(result) || Number.isNaN(parsed.valueOf()) || parsed.toISOString().slice(0, 10) !== result) {
    throw new Error(`${label} must use YYYY-MM-DD.`);
  }
  return result;
}

export function createCatalogMetricMap(rawMetrics: RawMetricDefinition[], catalog: IndexCatalog): Map<string, MetricDefinition> {
  const routes = new Map(catalog.fallbackRoutes.map(route => [route.metricId, route.fallbackMetricIds]));
  return new Map<string, MetricDefinition>([
    ...rawMetrics.map(metric => [metric.id, { ...metric, fallbackMetricIds: routes.get(metric.id) ?? [] }] as const),
    ...catalog.compositeMetrics.map(metric => [metric.id, metric] as const)
  ]);
}

export function parseIndexCatalog(input: unknown, rawMetrics: RawMetricDefinition[]): IndexCatalog {
  const data = record(input);
  if (!Array.isArray(data.compositeMetrics) || !Array.isArray(data.publishedIndices) || !Array.isArray(data.fallbackRoutes)) {
    throw new Error('Catalog requires compositeMetrics, publishedIndices and fallbackRoutes arrays.');
  }
  const families: MetricFamily[] = ['quality', 'speed', 'latency', 'cost', 'vision', 'knowledge'];
  const compositeMetrics: CompositeMetricDefinition[] = data.compositeMetrics.map((value: unknown) => {
    const metric = record(value);
    if (metric.kind !== 'composite' || !families.includes(metric.family as MetricFamily)) throw new Error('Invalid composite metric type.');
    if (!Array.isArray(metric.components) || metric.components.length === 0) throw new Error('Add at least one component.');
    if (metric.fallbackOnly !== undefined && typeof metric.fallbackOnly !== 'boolean') throw new Error('Invalid fallback-only flag.');
    const components = metric.components.map((value: unknown) => {
      const part = record(value);
      if (typeof part.weight !== 'number' || !Number.isFinite(part.weight) || part.weight < 0) throw new Error('Weights must be finite, non-negative numbers.');
      return { metricId: id(part.metricId), weight: part.weight };
    });
    if (Math.abs(components.reduce((sum, part) => sum + part.weight, 0) - 1) > 1e-8) throw new Error('Component weights must sum to 100%.');
    return {
      id: id(metric.id), version: text(metric.version, 'Formula version'),
      kind: 'composite', family: metric.family as MetricFamily,
      name: text(metric.name, 'Formula name'), description: text(metric.description, 'Description', true),
      ...(metric.fallbackOnly ? { fallbackOnly: true } : {}), components
    };
  });
  const publishedIndices: PublishedIndex[] = data.publishedIndices.map((value: unknown) => {
    const index = record(value);
    if (index.isDefault !== undefined && typeof index.isDefault !== 'boolean') throw new Error('Invalid default index flag.');
    return {
      id: id(index.id), version: text(index.version, 'Index version'), title: text(index.title, 'Index title'),
      lastUpdated: isoDate(index.lastUpdated, 'Index last updated date'),
      subtitle: text(index.subtitle, 'Subtitle', true), description: text(index.description, 'Description', true),
      rootMetricId: id(index.rootMetricId),
      ...(index.isDefault ? { isDefault: true } : {})
    };
  });
  const fallbackRoutes = data.fallbackRoutes.map((value: unknown) => {
    const route = record(value);
    if (!Array.isArray(route.fallbackMetricIds)) throw new Error('Fallbacks must be an ordered list.');
    const fallbackMetricIds = route.fallbackMetricIds.map(id);
    if (new Set(fallbackMetricIds).size !== fallbackMetricIds.length) throw new Error('Each fallback may appear only once in a route.');
    return { metricId: id(route.metricId), fallbackMetricIds };
  });
  if (new Set(fallbackRoutes.map(route => route.metricId)).size !== fallbackRoutes.length) throw new Error('Each benchmark has one fallback route.');
  const ids = [...rawMetrics, ...compositeMetrics].map(metric => metric.id);
  if (new Set(ids).size !== ids.length) throw new Error('Metric IDs must be unique.');
  if (new Set(publishedIndices.map(index => index.id)).size !== publishedIndices.length) throw new Error('Index IDs must be unique.');
  if (publishedIndices.filter(index => index.isDefault).length !== (publishedIndices.length ? 1 : 0)) {
    throw new Error('Choose exactly one default index.');
  }
  if (data.manualCalibrations !== undefined && !Array.isArray(data.manualCalibrations)) throw new Error('Manual calibrations must be an array.');
  const manualCalibrations = ((data.manualCalibrations ?? []) as unknown[]).map(value => {
    const entry = record(value);
    if (typeof entry.factor !== 'number' || !Number.isFinite(entry.factor) || entry.factor < 0) throw new Error('Manual calibration factors must be finite, non-negative numbers.');
    const targetMetricId = id(entry.targetMetricId);
    const sourceMetricId = id(entry.sourceMetricId);
    if (!fallbackRoutes.some(route => route.metricId === targetMetricId && route.fallbackMetricIds.includes(sourceMetricId))) {
      throw new Error('Manual calibration must reference a registered fallback route.');
    }
    return { targetMetricId, sourceMetricId, factor: entry.factor,
      targetSignature: text(entry.targetSignature, 'Target signature'), sourceSignature: text(entry.sourceSignature, 'Source signature'),
      rationale: text(entry.rationale, 'Manual calibration rationale') };
  });
  if (new Set(manualCalibrations.map(entry => `${entry.targetMetricId}:${entry.sourceMetricId}`)).size !== manualCalibrations.length) {
    throw new Error('Each fallback route may have one manual calibration.');
  }
  const catalog = { compositeMetrics, publishedIndices, fallbackRoutes, ...(manualCalibrations.length ? { manualCalibrations } : {}) };
  const map = createCatalogMetricMap(rawMetrics, catalog);
  for (const metric of compositeMetrics) validateMetricDAG(metric.id, map);
  for (const index of publishedIndices) {
    const root = map.get(index.rootMetricId);
    if (root?.kind === 'composite' && root.fallbackOnly) throw new Error('Fallback-only formulas cannot be published as indexes.');
    if (root?.kind !== 'composite') throw new Error(`Index "${index.title}" needs an existing composite formula.`);
  }
  for (const sharedId of sharedComparisonIds) {
    const shared = map.get(sharedId);
    if (shared?.kind === 'composite' && shared.fallbackOnly) throw new Error('Shared comparison formulas cannot be fallback-only.');
    if (shared?.kind !== 'composite') throw new Error('Speed and Affordability formulas are required by the comparison views.');
  }
  for (const route of fallbackRoutes) {
    const target = map.get(route.metricId);
    if (target?.kind !== 'raw') throw new Error('Fallback targets must be raw benchmarks.');
    for (const sourceId of route.fallbackMetricIds) {
      const source = map.get(sourceId);
      if (!source) throw new Error(`Unknown fallback '${sourceId}'.`);
      if (resolveEffectiveLeafWeights(sourceId, map).some(leaf => leaf.effectiveWeight > 0 && leaf.rawMetricId === target.id)) {
        throw new Error(`Fallback '${sourceId}' depends on its own target '${target.id}'.`);
      }
      if (target.requiresVisionInput && !requiresVision(source, map)) throw new Error('Vision benchmarks require a fallback with vision input.');
    }
  }
  return catalog;
}

export function formulaDependents(catalog: IndexCatalog, metricId: string): string[] {
  return [...catalog.compositeMetrics
    .filter(metric => metric.components.some(part => part.metricId === metricId))
    .map(metric => metric.name),
    ...catalog.fallbackRoutes.filter(route => route.fallbackMetricIds.includes(metricId)).map(route => `Fallback for ${route.metricId}`)];
}

