import type { CrossEffortCalibration, LeafContribution, MetricDefinition, MetricObservation, ModelRelease, RawMetricDefinition } from '../types';
import { normalizeRawValue } from './normalizer';

export const CROSS_EFFORT_POLICY = 'same-release-top-paired-capability-means-v1';
const isCapability = (metric: RawMetricDefinition) => ['quality', 'knowledge', 'vision'].includes(metric.family);

/** Fit each lower setting to its own release's direct Top measurements, independently of index weights. */
export function buildCrossEffortCalibrations(
  models: ModelRelease[], metrics: Map<string, MetricDefinition>, observations: Map<string, MetricObservation>
): Map<string, CrossEffortCalibration> {
  const result = new Map<string, CrossEffortCalibration>();
  for (const model of models) {
    const config = model.reasoningConfiguration;
    if (!config || !['middle', 'lowest'].includes(config.tier)) continue;
    const top = models.find(candidate => candidate.reasoningConfiguration?.releaseId === config.releaseId
      && candidate.reasoningConfiguration.tier === 'top' && candidate.isReasoningModel === model.isReasoningModel);
    if (!top) continue;
    const pairs: CrossEffortCalibration['pairs'] = [];
    for (const metric of metrics.values()) {
      if (metric.kind !== 'raw' || !isCapability(metric)) continue;
      if (metric.requiresVisionInput && (model.visionInput === 'unsupported' || top.visionInput === 'unsupported')) continue;
      const topObservation = observations.get(`${top.id}:${metric.id}`);
      const lowerObservation = observations.get(`${model.id}:${metric.id}`);
      if (!topObservation || !lowerObservation) continue;
      pairs.push({ metricId: metric.id, topObservation, lowerObservation,
        topPoints: normalizeRawValue(topObservation.value, metric),
        lowerPoints: normalizeRawValue(lowerObservation.value, metric) });
    }
    const topSum = pairs.reduce((sum, pair) => sum + pair.topPoints, 0);
    if (!pairs.length || topSum <= 0) continue;
    result.set(model.id, { topModelId: top.id, topEffort: top.reasoningConfiguration?.effort ?? null,
      factor: pairs.reduce((sum, pair) => sum + pair.lowerPoints, 0) / topSum, pairs });
  }
  return result;
}

/** Estimates stay out of the measurement pool, benchmark calibration and other estimates' inputs. */
export function estimateCrossEffort(
  missing: LeafContribution, model: ModelRelease, calibration: CrossEffortCalibration | undefined,
  observations: Map<string, MetricObservation>
): LeafContribution {
  const target = missing.rawMetric;
  if (missing.state !== 'missing' || !calibration || !isCapability(target)
    || (target.requiresVisionInput && model.visionInput === 'unsupported')) return missing;
  const top = observations.get(`${calibration.topModelId}:${target.id}`);
  if (!top) return missing;
  const normalizedValue = Math.max(0, Math.min(100, normalizeRawValue(top.value, target) * calibration.factor));
  return { ...missing, state: 'estimated', hasEvidence: true, rawValue: null,
    sourceObservation: top, sourceMetric: target, estimateKind: 'cross-effort', crossEffort: calibration,
    normalizedValue, pointsContributed: normalizedValue * missing.effectiveWeight,
    explanation: `Cross-effort estimate from this release's Top result (${calibration.topEffort ?? 'effort not published'}).`
      + ` Top normalized points × ${calibration.factor.toFixed(4)}, the ratio of lower/Top means across ${String(calibration.pairs.length)} shared measured capability benchmarks.` };
}

