import { MetricDefinition } from '../types';

export interface EffectiveLeafWeight {
  rawMetricId: string;
  effectiveWeight: number;
}

/**
 * Checks only whether attaching a candidate metric below a parent would create a cycle.
 * Weight validation remains the responsibility of validateMetricDAG.
 */
export function wouldCreateMetricCycle(
  parentMetricId: string,
  candidateMetricId: string,
  metricMap: Map<string, MetricDefinition>
): boolean {
  const visited = new Set<string>();

  function dependsOnParent(metricId: string): boolean {
    if (metricId === parentMetricId) return true;
    if (visited.has(metricId)) return false;
    visited.add(metricId);

    const metric = metricMap.get(metricId);
    if (!metric || metric.kind === 'raw') return false;
    return metric.components.some((component) => dependsOnParent(component.metricId));
  }

  return dependsOnParent(candidateMetricId);
}

/**
 * Validates that metric definitions form a valid Directed Acyclic Graph (no cycles).
 * Throws an Error with a descriptive message if a cycle is found or a reference is missing.
 */
export function validateMetricDAG(
  rootMetricId: string,
  metricMap: Map<string, MetricDefinition>
): void {
  const visited = new Set<string>();
  const recursionStack = new Set<string>();

  function dfs(metricId: string, path: string[]): void {
    if (recursionStack.has(metricId)) {
      throw new Error(`Cycle detected in metric definitions: ${[...path, metricId].join(' -> ')}`);
    }
    if (visited.has(metricId)) {
      return;
    }

    const metric = metricMap.get(metricId);
    if (!metric) {
      throw new Error(`Referenced metric '${metricId}' does not exist in metric definitions.`);
    }

    visited.add(metricId);
    recursionStack.add(metricId);

    if (metric.kind === 'composite') {
      let weightSum = 0;
      for (const comp of metric.components) {
        weightSum += comp.weight;
        dfs(comp.metricId, [...path, metricId]);
      }
      // Validate weight sum (allowing small floating point error)
      if (Math.abs(weightSum - 1.0) > 0.005) {
        throw new Error(
          `Composite metric '${metric.id}' components must sum to 1.0 (found ${weightSum.toFixed(4)})`
        );
      }
    }

    recursionStack.delete(metricId);
  }

  dfs(rootMetricId, []);
}

/**
 * Recursively resolves a root metric into a flattened list of effective leaf raw metrics and their weights.
 * Handles multi-tier compositions (e.g., Index -> CompositeSpeed -> RawSpeed1, RawSpeed2).
 */
export function resolveEffectiveLeafWeights(
  rootMetricId: string,
  metricMap: Map<string, MetricDefinition>
): EffectiveLeafWeight[] {
  validateMetricDAG(rootMetricId, metricMap);

  const leafWeights = new Map<string, number>();

  function traverse(metricId: string, currentWeight: number): void {
    const metric = metricMap.get(metricId);
    if (!metric) {
      throw new Error(`Referenced metric '${metricId}' does not exist in metric definitions.`);
    }

    if (metric.kind === 'raw') {
      const existing = leafWeights.get(metric.id) ?? 0;
      leafWeights.set(metric.id, existing + currentWeight);
    } else {
      for (const comp of metric.components) {
        traverse(comp.metricId, currentWeight * comp.weight);
      }
    }
  }

  traverse(rootMetricId, 1.0);

  return Array.from(leafWeights.entries()).map(([rawMetricId, effectiveWeight]) => ({
    rawMetricId,
    effectiveWeight
  }));
}

