import type { CrossEffortCalibration, FallbackSourceComponent, MetricDefinition, MetricObservation, ModelRelease } from '../types';
import { resolveEffectiveLeafWeights } from './dag';
import { normalizeRawValue } from './normalizer';

export function requiresVision(metric: MetricDefinition, metrics: Map<string, MetricDefinition>): boolean {
  return resolveEffectiveLeafWeights(metric.id, metrics).some(leaf => {
    const raw = metrics.get(leaf.rawMetricId);
    return leaf.effectiveWeight > 0 && raw?.kind === 'raw' && raw.requiresVisionInput;
  });
}

/** Runtime may estimate missing inputs from real Top measurements; calibration callers use measurements only. */
export function readFallbackSource(
  model: Pick<ModelRelease, 'id' | 'visionInput'>, metric: MetricDefinition, metrics: Map<string, MetricDefinition>,
  observations: Map<string, MetricObservation>, crossEffort?: CrossEffortCalibration
): { score: number; perfectVisionScore: number; components: FallbackSourceComponent[] } | null {
  const components: FallbackSourceComponent[] = [];
  for (const leaf of resolveEffectiveLeafWeights(metric.id, metrics)) {
    if (leaf.effectiveWeight <= 0) continue;
    const raw = metrics.get(leaf.rawMetricId);
    const observation = observations.get(`${model.id}:${leaf.rawMetricId}`);
    if (raw?.kind !== 'raw') return null;
    if (raw.requiresVisionInput && model.visionInput === 'unsupported') {
      // Match primary scoring: a recorded vision result conflicts with unsupported metadata.
      if (observation) return null;
      components.push({ metric: raw, state: 'unsupported', weight: leaf.effectiveWeight, normalizedValue: 0 });
      continue;
    }
    if (!observation) {
      const top = crossEffort && ['quality', 'knowledge', 'vision'].includes(raw.family)
        ? observations.get(`${crossEffort.topModelId}:${raw.id}`) : undefined;
      if (!top || !crossEffort) return null;
      components.push({ metric: raw, state: 'cross-effort', observation: top, weight: leaf.effectiveWeight,
        normalizedValue: Math.max(0, Math.min(100, normalizeRawValue(top.value, raw) * crossEffort.factor)) });
      continue;
    }
    components.push({ metric: raw, state: 'measured', observation, weight: leaf.effectiveWeight,
      normalizedValue: normalizeRawValue(observation.value, raw) });
  }
  return {
    score: components.reduce((sum, part) => sum + part.weight * part.normalizedValue, 0),
    perfectVisionScore: components.reduce((sum, part) => sum + part.weight * (part.state === 'unsupported' ? 100 : part.normalizedValue), 0),
    components
  };
}

