import { RawMetricDefinition } from '../types';

/**
 * Normalizes a raw metric observation into a 0-100 score using fixed immutable anchors.
 * Supports both 'higher' is better and 'lower' is better (e.g. latency, cost).
 */
export function normalizeRawValue(raw: number, definition: RawMetricDefinition): number {
  const { lowerAnchor, upperAnchor } = definition.normalization;

  if (upperAnchor === lowerAnchor) {
    return 50; // Guard against degenerate anchors
  }

  let normalized: number;

  if (definition.normalization.scale === 'log') {
    const bounded = Math.max(lowerAnchor, Math.min(upperAnchor, raw));
    const score = 100 * Math.log(upperAnchor / bounded) / Math.log(upperAnchor / lowerAnchor);
    return definition.direction === 'lower' ? score : 100 - score;
  }

  if (definition.direction === 'higher') {
    normalized = 100 * ((raw - lowerAnchor) / (upperAnchor - lowerAnchor));
  } else {
    // For lower is better: lowerAnchor represents worst (or high threshold), upperAnchor represents best (or low threshold)
    // Or standard convention: raw near lowerAnchor (e.g. $0) is 100, raw near upperAnchor (e.g. $5) is 0
    normalized = 100 * ((upperAnchor - raw) / (upperAnchor - lowerAnchor));
  }

  return Math.max(0, Math.min(100, normalized));
}

