import type { MetricDefinition, MetricObservation, ModelRelease } from '../types';
import { matchesReasoningConfiguration } from './reasoningConfigurations';

export const OBSERVATION_SELECTION_POLICY = 'exact-reasoning-configuration-unspecified-top-v2';

/** Best numeric result within one configuration; unspecified effort belongs only to Top. */
export function selectBestObservations(
  models: Pick<ModelRelease, 'id' | 'isReasoningModel' | 'reasoningConfiguration'>[], metrics: Map<string, MetricDefinition>, observations: MetricObservation[]
): Map<string, MetricObservation> {
  const modelMap = new Map(models.map(model => [model.id, model]));
  const selected = new Map<string, MetricObservation>();
  for (const observation of observations) {
    const model = modelMap.get(observation.modelId);
    const metric = metrics.get(observation.metricId);
    if (!model || metric?.kind !== 'raw') continue;
    const mode = model.isReasoningModel ? 'reasoning' : 'non-reasoning';
    if (observation.reasoningMode && observation.reasoningMode !== mode) continue;
    if (!matchesReasoningConfiguration(model, observation)) continue;
    const key = `${model.id}:${metric.id}`;
    const previous = selected.get(key);
    if (!previous || (metric.direction === 'higher'
      ? observation.value > previous.value : observation.value < previous.value)) {
      selected.set(key, observation);
    }
  }
  return selected;
}

src/engine/pareto.ts:
import { AxisObjective } from '../types';

export interface ParetoItem<T> {
  id: string;
  x: number;
  y: number;
  data: T;
}

export interface ParetoResult<T> {
  allItems: (ParetoItem<T> & { isFrontier: boolean })[];
  frontierItems: (ParetoItem<T> & { isFrontier: boolean })[];
}

/**
 * Calculates the non-dominated Pareto frontier for any pair of axis optimization objectives.
 * E.g., minimize Cost (X) + maximize Quality (Y)
 * or minimize Time (X) + minimize Cost (Y)
 */
export function computeParetoFrontier<T>(
  items: ParetoItem<T>[],
  xObjective: AxisObjective,
  yObjective: AxisObjective
): ParetoResult<T> {
  if (items.length === 0) {
    return { allItems: [], frontierItems: [] };
  }

  // Filter out any invalid numbers
  const validItems = items.filter(
    (item) => !isNaN(item.x) && !isNaN(item.y) && isFinite(item.x) && isFinite(item.y)
  );

  const frontierSet = new Set<string>();

  for (const candidate of validItems) {
    let isDominated = false;

    for (const opponent of validItems) {
      if (candidate.id === opponent.id) continue;

      const xBetterOrEqual =
        xObjective === 'maximize' ? opponent.x >= candidate.x : opponent.x <= candidate.x;
      const yBetterOrEqual =
        yObjective === 'maximize' ? opponent.y >= candidate.y : opponent.y <= candidate.y;

      const xStrictlyBetter =
        xObjective === 'maximize' ? opponent.x > candidate.x : opponent.x < candidate.x;
      const yStrictlyBetter =
        yObjective === 'maximize' ? opponent.y > candidate.y : opponent.y < candidate.y;

      if (xBetterOrEqual && yBetterOrEqual && (xStrictlyBetter || yStrictlyBetter)) {
        isDominated = true;
        break;
      }
    }

    if (!isDominated) {
      frontierSet.add(candidate.id);
    }
  }

  const allItems = validItems.map((item) => ({
    ...item,
    isFrontier: frontierSet.has(item.id)
  }));

  // Sort frontier points monotonically along the X axis for SVG path drawing
  const frontierItems = allItems
    .filter((item) => item.isFrontier)
    .sort((a, b) => a.x - b.x);

  return {
    allItems,
    frontierItems
  };
}

