export const TOKEN_PRICE_BLEND = { cachedInput: 0.7, input: 0.2, output: 0.1 } as const;

/** USD per million total tokens, using AA's 7:2:1 cache-hit/input/output mix. */
export function blendTokenPrice(rates: { cachedInput: number; input: number; output: number }): number {
  return rates.cachedInput * TOKEN_PRICE_BLEND.cachedInput
    + rates.input * TOKEN_PRICE_BLEND.input
    + rates.output * TOKEN_PRICE_BLEND.output;
}

