import type { MetricObservation, ModelRelease, ReasoningConfiguration } from '../types';

type ConfiguredModel = Pick<ModelRelease, 'id' | 'isReasoningModel' | 'reasoningConfiguration'>;

/** A harness's "high" tier is not necessarily the provider's native effort. */
export function observationEffort(observation: MetricObservation): string | null {
  if (observation.configurationEffort !== undefined) return observation.configurationEffort;
  const budget = observation.reasoningBudget?.trim().toLowerCase();
  if (!budget || /not published|unspecified|not established|standard configuration|best score at any effort|unknown/.test(budget)) return null;
  if (observation.sourceUrl.includes('playground.roboflow.com')) return null;
  const named = /^(max|xhigh|high|medium|low)(?:\s*\(source\))?$/.exec(budget);
  if (named && observation.modelId.startsWith('deepseek-v4') && ['medium', 'xhigh'].includes(named[1])) return 'high';
  // Preserve explicit token budgets or other harness settings; do not call them unspecified.
  return named?.[1] ?? budget;
}

export function matchesReasoningConfiguration(model: ConfiguredModel, observation: MetricObservation): boolean {
  if (observation.reasoningMode && observation.reasoningMode !== (model.isReasoningModel ? 'reasoning' : 'non-reasoning')) return false;
  const config = model.reasoningConfiguration;
  if (!config) return true;
  // Token rates describe the release's endpoint, not a benchmark's reasoning run.
  if (observation.metricId === 'blended-token-price') return true;
  const effort = observationEffort(observation);
  if (effort === null) return config.tier === 'top' || config.tier === 'single';
  return effort === config.effort;
}

/** Route release-level evidence into exact configurations without cross-effort fallback. */
export function assignReasoningObservations(
  models: ConfiguredModel[], observations: MetricObservation[]
): MetricObservation[] {
  return observations.flatMap(observation => models.flatMap(model => {
    const config = model.reasoningConfiguration;
    if (observation.modelId !== model.id && observation.modelId !== config?.releaseId) return [];
    if (!matchesReasoningConfiguration(model, observation)) return [];
    if (!config) return [observation];
    const effort = observationEffort(observation);
    return [{
      ...observation, modelId: model.id,
      effortAttribution: observation.metricId === 'blended-token-price' ? 'shared-price' as const
        : effort === null ? 'assumed-top' as const : 'explicit' as const
    }];
  }));
}

export function configurationSetting(config: ReasoningConfiguration): string {
  return config.effort === null ? 'Reasoning enabled; effort not published' : 'Reasoning enabled; ' + config.effort;
}

