import type { CalculatedModelScore } from '../types';

export function formatMargin(margin: number | null): string {
  return margin === null ? '' : `±${String(Math.round(margin))}`;
}

// Score points retain one decimal; the absolute margin rounds to the nearest whole point.
export function formatScore(score: CalculatedModelScore): string {
  const central = score.score.toFixed(1);
  const margin = formatMargin(score.uncertainty.margin);
  return `${central}${margin ? ` ${margin}` : ''}`;
}

src/engine/uncertainty.ts:
import type { LeafContribution, ScoreUncertainty } from '../types';

// Editorial substitution allowance in benchmark points, already a ± radius.
export const FALLBACK_MARGIN_POINTS = 10;

export function calculateScoreUncertainty(leaves: LeafContribution[], isEligible: boolean): ScoreUncertainty {
  if (!isEligible) return { status: 'unavailable', margin: null, method: 'none',
    explanation: 'Less than 95% coverage; the score remains provisional.' };
  const fallbackWeight = leaves.filter(leaf => leaf.state === 'estimated' && leaf.estimateKind !== 'cross-effort')
    .reduce((sum, leaf) => sum + leaf.effectiveWeight, 0);
  const crossEffortWeight = leaves.filter(leaf => leaf.estimateKind === 'cross-effort')
    .reduce((sum, leaf) => sum + leaf.effectiveWeight, 0);
  const coverageGap = leaves.filter(leaf => leaf.state === 'missing')
    .reduce((sum, leaf) => sum + leaf.effectiveWeight * 100, 0);
  if (fallbackWeight === 0 && crossEffortWeight === 0 && coverageGap === 0) return { status: 'not-needed', margin: null, method: 'none',
    explanation: 'No substitution or missing-coverage allowance applies. Direct benchmark measurement noise is not quantified.' };
  const fallbackMargin = fallbackWeight * FALLBACK_MARGIN_POINTS;
  const crossEffortMargin = crossEffortWeight * FALLBACK_MARGIN_POINTS;
  const coverageMargin = coverageGap / 2;
  return { status: 'available', margin: fallbackMargin + crossEffortMargin + coverageMargin, method: 'policy',
    explanation: `Substitution allowance: ${fallbackMargin.toFixed(2)} points (${String(FALLBACK_MARGIN_POINTS)} × fallback weight).`
      + (crossEffortWeight > 0 ? ` Plus ${crossEffortMargin.toFixed(2)} points (${String(FALLBACK_MARGIN_POINTS)} × cross-effort estimated weight).` : '')
      + (coverageGap > 0 ? ` Plus ${coverageMargin.toFixed(2)} points, half the ${coverageGap.toFixed(2)}-point coverage gap. Missing components retain zero score contribution.` : '')
      + ' Benchmark disagreement does not increase this allowance. This is an editorial uncertainty indicator, not a statistical confidence interval or a bound on possible results.' };
}

src/types/index.ts:
export type MetricFamily = 'quality' | 'speed' | 'latency' | 'cost' | 'vision' | 'knowledge';
export type OptimizationDirection = 'higher' | 'lower';
export type AxisObjective = 'minimize' | 'maximize';
export type ScaleType = 'linear' | 'log';

export interface RawMetricDefinition {
  id: string;
  version: string;
  kind: 'raw';
  family: MetricFamily;
  name: string;
  shortName: string;
  /** Whether the registered evaluation requires native image input. */
  requiresVisionInput: boolean;
  /** Ordered alternatives, used only with a version-matched calibration. */
  fallbackMetricIds?: string[];
  unit: string;
  direction: OptimizationDirection;
  normalization: {
    scale?: ScaleType;
    lowerAnchor: number;
    upperAnchor: number;
    clamp: true;
  };
  source: {
    benchmarkName: string;
    primarySourceUrl: string;
    citation: string;
    description: string;
  };
}

export interface CompositeMetricDefinition {
  id: string;
  version: string;
  kind: 'composite';
  family: MetricFamily;
  name: string;
  description: string;
  /** Internal formula, editable in Studio but not published as an index or comparison axis. */
  fallbackOnly?: boolean;
  components: {
    metricId: string; // References a RawMetricDefinition or another CompositeMetricDefinition
    weight: number;   // Normalization requires sum = 1.0 within tolerance
  }[];
}

export type MetricDefinition = RawMetricDefinition | CompositeMetricDefinition;

export interface PublishedIndex {
  id: string;
  version: string;
  lastUpdated: string;
  title: string;
  subtitle: string;
  description: string;
  rootMetricId: string;
  isDefault?: boolean;
}

export interface MetricObservation {
  /** Native setting when established separately from the source's display label; null means unspecified. */
  configurationEffort?: string | null;
  effortAttribution?: 'explicit' | 'assumed-top' | 'shared-price';
  modelId: string;
  metricId: string;
  value: number;
  observationDate: string; // ISO 8601 YYYY-MM-DD
  sourceUrl: string;
  scaffoldOrHarness?: string;
  reasoningBudget?: string;
  /** Populate when the source establishes reasoning on/off; omitted means unknown, not a mismatch. */
  reasoningMode?: 'reasoning' | 'non-reasoning';
  notes?: string;
}

export interface ModelRelease {
  reasoningConfiguration?: ReasoningConfiguration;
  id: string;
  visionInput: 'supported' | 'unsupported' | 'unknown';
  visionSourceUrl?: string;
  name: string;
  shortName: string;
  organization: string;
  access: 'api' | 'open_weights' | 'hosted';
  license: string;
  releaseDate: string;
  contextWindow: number;
  isReasoningModel: boolean;
  description: string;
  badge?: string;
}

/** Only identity, mode and modality are needed to contribute calibration evidence. */
export type CalibrationModel = Pick<ModelRelease, 'id' | 'name' | 'isReasoningModel' | 'visionInput' | 'reasoningConfiguration'>;

export interface ReasoningConfiguration {
  releaseId: string;
  tier: 'top' | 'middle' | 'lowest' | 'single';
  effort: string | null;
  sourceUrl: string;
  basis: 'shared-benchmarks' | 'documented-settings' | 'single';
}

export interface CalibrationReferenceData {
  models: CalibrationModel[];
  observations: MetricObservation[];
}

export interface LeafContribution {
  rawMetric: RawMetricDefinition;
  state: 'measured' | 'estimated' | 'unsupported' | 'missing';
  /** A primary result, calibrated fallback, or confirmed unsupported-vision zero resolves this component. */
  hasEvidence: boolean;
  sourceObservation?: MetricObservation;
  sourceMetric?: MetricDefinition;
  sourceComponents?: FallbackSourceComponent[];
  calibrationId?: string;
  estimateKind?: 'scaled' | 'cross-effort';
  crossEffort?: CrossEffortCalibration;
  explanation: string;
  rawValue: number | null;
  normalizedValue: number;
  effectiveWeight: number;
  pointsContributed: number;
  /** Normalized target score with unsupported fallback inputs at 100, using the same conversion. */
  perfectVisionValue?: number;
}

export interface CalculatedModelScore {
  model: ModelRelease;
  score: number;
  rank: number | null;
  isEligible: boolean;
  coveragePercent: number;
  measuredPercent: number;
  estimatedPercent: number;
  crossEffortEstimatedPercent: number;
  unsupportedPercent: number;
  perfectVisionScore: number;
  uncertainty: ScoreUncertainty;
  leafBreakdown: LeafContribution[];
}

export interface CrossEffortCalibration {
  topModelId: string;
  topEffort: string | null;
  factor: number;
  pairs: {
    metricId: string;
    topObservation: MetricObservation;
    lowerObservation: MetricObservation;
    topPoints: number;
    lowerPoints: number;
  }[];
}

export interface FallbackCalibration {
  id: string;
  targetMetricId: string;
  sourceMetricId: string;
  targetSignature: string;
  sourceSignature: string;
  targetReferenceCount: number;
  sourceReferenceCount: number;
  pairedCount: number;
  method: 'paired-mean' | 'manual' | null;
  status: 'ready' | 'manual-required';
  reason: string;
  scale: { sourceAnchor: number; targetAnchor: number } | null;
}

export interface ManualFallbackCalibration {
  targetMetricId: string;
  sourceMetricId: string;
  targetSignature: string;
  sourceSignature: string;
  factor: number;
  rationale: string;
}

export interface ScoreUncertainty {
  status: 'available' | 'unavailable' | 'not-needed';
  margin: number | null;
  method: 'policy' | 'none';
  explanation: string;
}

export interface IndexCatalog {
  /** Approved manual factors; proposals stay outside the active catalog. */
  manualCalibrations?: ManualFallbackCalibration[];
  compositeMetrics: CompositeMetricDefinition[];
  publishedIndices: PublishedIndex[];
  fallbackRoutes: { metricId: string; fallbackMetricIds: string[] }[];
}

export type FallbackSourceComponent = {
  metric: RawMetricDefinition;
  weight: number;
  normalizedValue: number;
} & ({ state: 'measured' | 'cross-effort'; observation: MetricObservation } | { state: 'unsupported'; observation?: never });

